import { can, type Action, type PermissionResult } from './permissions';
import { ROLES, type DemoState, type DemoUser, type ResourceRequest, type Role } from './types';

/**
 * The permission matrix shown on the Roles screen is GENERATED by calling the
 * real `can()` for every role, never hand-written. If a rule changes in
 * permissions.ts, this table changes with it.
 *
 * Two honesty rules are baked in:
 *  - a row that needs an entity records the fixture it was evaluated against,
 *    and is flagged as conditional, so no cell can be read as "always allowed";
 *  - the conditional cases (self-approval, owning an allocation) get their own
 *    evaluations rather than being summarised away.
 */

export interface MatrixCell extends PermissionResult {
  role: Role;
}

export interface MatrixRow {
  action: Action;
  label: string;
  /** Empty for actions that take no entity. */
  fixture: string;
  conditional: boolean;
  cells: MatrixCell[];
}

export interface ConditionalCase {
  id: string;
  label: string;
  description: string;
  cells: MatrixCell[];
}

export interface PermissionMatrix {
  /** One representative persona per role, taken from the demo users. */
  personas: DemoUser[];
  rows: MatrixRow[];
  conditionals: ConditionalCase[];
}

/** A request object built purely for evaluation. It is never added to state. */
function fixtureRequest(requesterId: string, status: ResourceRequest['status'] = 'PENDING'): ResourceRequest {
  return {
    id: 'fixture-request',
    code: 'RF-0000',
    title: 'Permission fixture',
    purpose: 'Used only to evaluate the permission rules on this screen.',
    requesterId,
    items: [],
    durationDays: 1,
    status,
    createdAt: '2026-01-01T00:00:00.000Z',
  };
}

function personaFor(state: DemoState, role: Role): DemoUser | undefined {
  return state.users.find((u) => u.role === role);
}

function evaluate(personas: DemoUser[], action: Action, context: (actor: DemoUser) => Parameters<typeof can>[2]): MatrixCell[] {
  return personas.map((actor) => ({ role: actor.role, ...can(actor, action, context(actor)) }));
}

/** Someone who is definitely not the actor, for "a request filed by someone else". */
const OTHER_PERSON = 'fixture-other-user';

export function buildPermissionMatrix(state: DemoState): PermissionMatrix {
  const personas = ROLES.map((role) => personaFor(state, role)).filter((u): u is DemoUser => Boolean(u));

  const foreignPending = () => ({ request: fixtureRequest(OTHER_PERSON, 'PENDING') });

  const rows: MatrixRow[] = [
    {
      action: 'request:create',
      label: 'Create a resource request',
      fixture: '',
      conditional: false,
      cells: evaluate(personas, 'request:create', () => ({})),
    },
    {
      action: 'request:viewAll',
      label: 'Browse every request in the demo',
      fixture: '',
      conditional: false,
      cells: evaluate(personas, 'request:viewAll', () => ({})),
    },
    {
      action: 'request:viewOne',
      label: 'Open a single request',
      fixture: 'a PENDING request filed by someone else',
      conditional: true,
      cells: evaluate(personas, 'request:viewOne', foreignPending),
    },
    {
      action: 'request:cancel',
      label: 'Cancel a request',
      fixture: 'a PENDING request filed by someone else',
      conditional: true,
      cells: evaluate(personas, 'request:cancel', foreignPending),
    },
    {
      action: 'request:decide',
      label: 'Approve or reject a request',
      fixture: 'a PENDING request filed by someone else',
      conditional: true,
      cells: evaluate(personas, 'request:decide', foreignPending),
    },
    {
      action: 'allocation:create',
      label: 'Allocate resources',
      fixture: '',
      conditional: false,
      cells: evaluate(personas, 'allocation:create', () => ({})),
    },
    {
      action: 'allocation:return',
      label: 'Return an allocation',
      fixture: "an allocation behind someone else's request",
      conditional: true,
      cells: evaluate(personas, 'allocation:return', foreignPending),
    },
    {
      action: 'allocation:expire',
      label: 'Force an allocation to expire',
      fixture: '',
      conditional: false,
      cells: evaluate(personas, 'allocation:expire', () => ({})),
    },
    {
      action: 'capacity:manage',
      label: 'Manage pool capacity',
      fixture: '',
      conditional: false,
      cells: evaluate(personas, 'capacity:manage', () => ({})),
    },
    {
      action: 'demo:reset',
      label: 'Reset the demo data',
      fixture: '',
      conditional: false,
      cells: evaluate(personas, 'demo:reset', () => ({})),
    },
  ];

  const own = (actor: DemoUser) => ({ request: fixtureRequest(actor.id, 'PENDING') });

  const conditionals: ConditionalCase[] = [
    {
      id: 'decide-own',
      label: 'Decide a request you filed yourself',
      description:
        'Separation of duties. Holding the Approver or Administrator role does not let you clear your own request — the same rule the Approval Queue shows as "Your own request".',
      cells: evaluate(personas, 'request:decide', own),
    },
    {
      id: 'view-own',
      label: 'Open your own request',
      description: 'Everyone can read back what they filed, whatever their role.',
      cells: evaluate(personas, 'request:viewOne', own),
    },
    {
      id: 'cancel-own',
      label: 'Cancel your own PENDING request',
      description:
        'The owner may withdraw a request while it is still pending. The workflow also refuses this once the request has left PENDING.',
      cells: evaluate(personas, 'request:cancel', own),
    },
    {
      id: 'return-own',
      label: 'Return the allocation behind your own request',
      description:
        'A requester may hand back resources they asked for. An Approver who does not own the request may not, even though they can approve requests.',
      cells: evaluate(personas, 'allocation:return', own),
    },
  ];

  return { personas, rows, conditionals };
}
